def repl(start,end,body):
    global s
    pat=re.escape(start)+r'.*?(?='+re.escape(end)+r')'
    ns,n=re.subn(pat,body+'\n ',s,flags=re.S)
    if n!=1: raise SystemExit(f'patch failed {start} n={n}')
    s=ns

repl('void nav(){','void render(){',r'''void nav(){nav.removeAllViews();String[][] a={{"⌂\n首页","home"},{"★\n精选","picks"},{"▣\n战绩","record"},{"◇\n深度","depth"},{"●\n我的","me"}};for(String[]x:a){boolean on=page.equals(x[1]);TextView t=tv(x[0],12,on?orange:0xFF666666,on);t.setGravity(Gravity.CENTER);t.setLines(2);t.setOnClickListener(v->{page=x[1];render();});nav.addView(t,new LinearLayout.LayoutParams(0,dp(58),1));}}''')
