repl('LinearLayout homeCard(JSONObject o){','void detail(JSONObject o){',r'''LinearLayout homeCard(JSONObject o){LinearLayout c=card();String d=o.optString("publish_date"),no=fmtNo(o.optString("match_no"));boolean feat=isFormalFeatured(d,o.optString("match_no")),warn=isRiskMatch(d,o.optString("match_no"));ArrayList<JSONObject> ps=pickList(d,o.optString("match_no"));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(tv(no+"  "+o.optString("league"),12,muted,true),new LinearLayout.LayoutParams(0,-2,1));if(feat){TextView tag=tv("精选",11,Color.WHITE,true);tag.setBackground(box(orange,10));tag.setPadding(dp(8),dp(3),dp(8),dp(3));top.addView(tag);}else if(warn){TextView tag=tv("⚠ 预警",11,0xFFB46A16,true);tag.setBackground(box(0xFFFFF1D8,10));tag.setPadding(dp(8),dp(3),dp(8),dp(3));top.addView(tag);}c.addView(top);TextView teams=tv(o.optString("home_team")+"   VS   "+o.optString("away_team"),17,dark,true);teams.setGravity(Gravity.CENTER);teams.setPadding(0,dp(10),0,dp(8));c.addView(teams);String rs=o.optString("result_text");String st=feat?featuredStatus(ps):"";LinearLayout foot=new LinearLayout(this);foot.setGravity(Gravity.CENTER_VERTICAL);foot.addView(tv(rs.isEmpty()?"未开赛":"完场  "+rs,12,muted,false),new LinearLayout.LayoutParams(0,-2,1));if(!st.isEmpty())foot.addView(tv(st,12,st.contains("成功")?green:st.contains("未中")?red:orange,true));c.addView(foot);c.setOnClickListener(v->detail(o));return c;}''')
repl('void detail(JSONObject o){','void fullPage(){',r'''void detail(JSONObject o){String d=o.optString("publish_date"),n=o.optString("match_no");ArrayList<JSONObject> ps=pickList(d,n);boolean feat=isFormalFeatured(d,n);LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(LinearLayout.VERTICAL);wrap.setPadding(dp(18),0,dp(18),0);wrap.addView(tv(fmtNo(n)+"  "+o.optString("league"),12,orange,true));TextView tm=tv(o.optString("home_team")+"  VS  "+o.optString("away_team"),21,dark,true);tm.setGravity(Gravity.CENTER);tm.setPadding(0,dp(8),0,dp(10));wrap.addView(tm);String k=o.optString("kickoff_bjt");if(!k.isEmpty())wrap.addView(tv("比赛时间  "+k.replace("T"," ").replace("+00:00",""),12,muted,false));wrap.addView(tv("核心推荐",17,dark,true));if(!feat)wrap.addView(tv("本场未进入正式精选 · 建议结合风险提示查看",14,muted,true));else{int max=Math.min(2,ps.size());for(int i=0;i<max;i++){JSONObject q=ps.get(i);if(!"正式前瞻".equals(q.optString("record_kind")))continue;LinearLayout b=card();b.setBackground(box(i==0?0xFFFFF0E8:0xFFFFF8EE,14));b.addView(tv(catName(q.optString("category")),12,muted,true));b.addView(tv(q.optString("selected_pick"),19,i==0?0xFFD9362B:orange,true));b.addView(tv("信心  "+stars(q.optInt("star_level",0)),12,muted,false));wrap.addView(b);} }JSONObject rr=riskFor(d,n);String reason=rr.optString("risk_reason");if(!reason.isEmpty()){wrap.addView(tv("风险提示",15,red,true));wrap.addView(tv(sanitize(reason),13,0xFFB46A16,false));}String rs=o.optString("result_text");if(!rs.isEmpty()){String ev=feat?featuredStatus(ps):"";wrap.addView(tv("赛后结果",15,dark,true));wrap.addView(tv("比分  "+rs+(ev.isEmpty()?"":"   "+ev),14,ev.contains("成功")?green:ev.contains("未中")?red:dark,true));}new AlertDialog.Builder(this).setTitle("比赛详情").setView(wrap).setPositiveButton("关闭",null).show();}''')
repl('void picksPage(){','String featuredStatus(ArrayList<JSONObject>a){',r'''void picksPage(){LinearLayout head=card();head.addView(tv("精选推荐",22,dark,true));head.addView(tv("只展示达到门槛的少量比赛 · 不够强就 PASS",12,muted,false));body.addView(head);LinkedHashMap<String,ArrayList<JSONObject>> groups=new LinkedHashMap<>();for(int i=0;i<picks.length();i++){JSONObject o=picks.optJSONObject(i);if(!day.equals(o.optString("publish_date")))continue;String k=o.optString("match_no");groups.computeIfAbsent(k,x->new ArrayList<>()).add(o);}if(groups.isEmpty()){LinearLayout c=card();c.addView(tv("该日期暂无精选记录",18,dark,true));c.addView(tv("没有达到客户精选门槛的比赛，宁可不推。",13,muted,false));body.addView(c);return;}for(Map.Entry<String,ArrayList<JSONObject>> e:groups.entrySet()){ArrayList<JSONObject>a=e.getValue();a.sort((x,y)->Integer.compare(x.optInt("recommendation_rank",99),y.optInt("recommendation_rank",99)));JSONObject f=a.get(0);LinearLayout c=card();LinearLayout top=new LinearLayout(this);top.addView(tv(fmtNo(e.getKey())+"  "+f.optString("league"),12,muted,true),new LinearLayout.LayoutParams(0,-2,1));String rk=f.optString("record_kind");top.addView(tv(rk.equals("历史回放")?"历史回放":"正式前瞻",11,rk.equals("历史回放")?muted:orange,true));c.addView(top);c.addView(tv(f.optString("home_team")+"  VS  "+f.optString("away_team"),17,dark,true));int max=Math.min(2,a.size());for(int j=0;j<max;j++){JSONObject q=a.get(j);c.addView(tv(catName(q.optString("category"))+"  "+q.optString("selected_pick")+"  "+stars(q.optInt("star_level",0)),15,j==0?0xFFD9362B:orange,true));}String st=featuredStatus(a);c.addView(tv(st,13,st.contains("成功")?green:st.contains("未中")?red:muted,true));body.addView(c);}}''')
repl('void recordPage(){','int[] stat(ArrayList<JSONObject>a,int days){',r'''void recordPage(){ArrayList<JSONObject> formal=new ArrayList<>(),hist=new ArrayList<>();for(int i=0;i<picks.length();i++){JSONObject q=picks.optJSONObject(i);String ss=q.optString("settle_status");if(!(ss.equals("命中")||ss.equals("未中")||ss.contains("成功")||ss.contains("失败")))continue;if("正式前瞻".equals(q.optString("record_kind")))formal.add(q);else if("历史回放".equals(q.optString("record_kind")))hist.add(q);}LinearLayout c=card();c.addView(tv("历史战绩",22,dark,true));int[] h7=stat(hist,7),h30=stat(hist,30),hall=stat(hist,99999);c.addView(tv("历史回放\n近7日  "+fmtStat(h7)+"\n近30日  "+fmtStat(h30)+"\n累计  "+fmtStat(hall),14,dark,true));c.addView(tv("历史回放用于模型复核，不冒充当日公开实战。",11,muted,false));body.addView(c);LinearLayout f=card();f.addView(tv("正式前瞻实战",19,dark,true));int[] f7=stat(formal,7),f30=stat(formal,30),fall=stat(formal,99999);f.addView(tv("近7日  "+fmtStat(f7)+"\n近30日  "+fmtStat(f30)+"\n累计  "+fmtStat(fall),14,dark,true));f.addView(tv("只统计真正赛前冻结且赛果确认的正式发布记录。",11,muted,false));body.addView(f);}''')
